/**
 * Creates every community named in the category workbook's "Community Tags"
 * column (data/communities.json, generated by
 * apps/web/scripts/category-import/generate.py).
 *
 * Run: pnpm --filter @slotbook/db seed:communities
 *
 * Idempotent: existing slugs are skipped, so re-running adds only new names and
 * never touches a community people already use. They start empty rather than
 * auto-joining the admin, so member counts reflect real members. Each gets a
 * topic-matching cover photo (community-covers.ts); covers for communities that
 * already exist are filled by backfill-community-covers.ts.
 */
import { readFileSync } from "node:fs";
import { PrismaClient, Role } from "@prisma/client";
import { assignCoverImages } from "./community-covers";

const prisma = new PrismaClient();

const BATCH_SIZE = 500;

interface SeedCommunity {
  name: string;
  slug: string;
  description: string;
}

async function main() {
  const communities = assignCoverImages(
    JSON.parse(readFileSync(new URL("./data/communities.json", import.meta.url), "utf8")) as SeedCommunity[],
  );

  const admin = await prisma.user.findFirst({
    where: { role: Role.ADMIN },
    orderBy: { createdAt: "asc" },
    select: { id: true, email: true },
  });
  if (!admin) throw new Error("No admin user found to own the communities. Run `pnpm db:seed` first.");

  let created = 0;
  for (let i = 0; i < communities.length; i += BATCH_SIZE) {
    const batch = communities.slice(i, i + BATCH_SIZE);
    const result = await prisma.community.createMany({
      data: batch.map((c) => ({ ...c, creatorId: admin.id })),
      skipDuplicates: true,
    });
    created += result.count;
  }

  console.log(`${created} communities created, ${communities.length - created} already existed (owner: ${admin.email}).`);
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
